  recipes(26) = '' // nl // '### 26. СЕЛЁДКА ПОД ШУБОЙ (6 порций)' // nl // 'Ингредиенты:' // nl // '  сельдь слабосолёная 500 г, картофель 4 шт,' // nl // '  свёкла 2 шт, морковь 1 шт, яйца 2 шт,' // nl // '  лук 1 шт, майонез 150 г, яблоко 1 шт.' // nl // 'Приготовление:' // nl // '  1. Сельдь вымочить 2 ч, обсушить, нарезать ломтиками.' // nl // '  2. Отварить картофель, свёклу, морковь, яйца.' // nl // '  3. Нарезать всё кубиком 5 мм.' // nl // '  4. Смешать сельдь с майонезом и зелёным луком.' // nl // '  5. Выложить слоями: сельдя, картофель, морковь, свёкла,' // nl // '  6. яйцо. Каждый слой смазать майонезом.' // nl // '  7. Дать настояться в холодильнике 4 часа.' // nl // ''
  recipes(27) = '' // nl // '### 27. САЛАТ МИМОЗА (6 порций)' // nl // 'Ингредиенты:' // nl // '  картофель 4 шт, морковь 3 шт, яйца 5 шт,' // nl // '  рыба консервированная в масле 250 г,' // nl // '  сливочное масло 80 г, майонез 100 г, укроп.' // nl // 'Приготовление:' // nl // '  1. Отварить картофель, морковь и 4 яйца (10 мин).' // nl // '  2. Нарезать всё кубиком 5 мм.' // nl // '  3. Размять рыбу с маслом и добавить в салат.' // nl // '  4. Заправить майонезом, посолить, поперчить.' // nl // '  5. Выложить горкой и посыпать яичным желтком, нарезанным соломкой.' // nl // '  6. Украсить укропом. В холодильник на 2 часа.' // nl // ''
  recipes(28) = '' // nl // '### 28. САЛАТ ЦЕЗАРЬ с курицей (4 порции)' // nl // 'Ингредиенты:' // nl // '  салат романо 1 кочан, куриное филе 400 г,' // nl // '  пармезан 80 г, сухарики 100 г, соус 150 г,' // nl // '  черри 100 г, масло, чеснок, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Курицу замариновать в масле с чесноком на 30 мин.' // nl // '  2. Обжарить на сковороде 6-7 мин, нарезать ломтиками.' // nl // '  3. Салат порвать, вымыть и обсушить.' // nl // '  4. Смешать с соусом, сверху курица и сухарики.' // nl // '  5. Посыпать пармезаном, добавить черри. Сразу подавать.' // nl // ''
  recipes(29) = '' // nl // '### 29. ВИНЕГРЕТ классический (6 порций)' // nl // 'Ингредиенты:' // nl // '  свёкла 3 шт, картофель 3 шт, морковь 2 шт,' // nl // '  огурцы солёные 3 шт, капуста квашеная 200 г,' // nl // '  лук 1 шт, фасоль 200 г, масло растительное.' // nl // 'Приготовление:' // nl // '  1. Свёклу, картофель, морковь отварить или запечь.' // nl // '  2. Остудить и нарезать кубиком 1 см.' // nl // '  3. Остальные овощи нарезать так же.' // nl // '  4. Соединить всё, заправить маслом, солью, перцем.' // nl // '  5. Дать настояться 2 часа — вкус раскроется.' // nl // ''
  recipes(30) = '' // nl // '### 30. ТАБАТЕ средиземноморский (6 порций)' // nl // 'Ингредиенты:' // nl // '  куриное филе 600 г, нут 200 г, кускус 150 г,' // nl // '  помидоры черри 200 г, перец болгарский 1 шт,' // nl // '  лук 1 шт, чеснок 2 зубчика, зелень, лимон.' // nl // 'Приготовление:' // nl // '  1. Курицу отварить, остудить и нарезать кубиком.' // nl // '  2. Нут заранее замочить и отварить.' // nl // '  3. Овощи нарезать мелко, зелень порубить.' // nl // '  4. Смешать всё с кускусом и заправкой из масла и лимона.' // nl // '  5. Дать постояться 20 мин, чтобы кускус набух.' // nl // ''
  recipes(31) = '' // nl // '### 31. САЛАТ с курицей и овощами (4 порции)' // nl // 'Ингредиенты:' // nl // '  куриное филе 400 г, огурец 1 шт, помидор 2 шт,' // nl // '  салат 100 г, кукуруза 100 г, йогурт 150 г,' // nl // '  чеснок, соль-перец, зелень.' // nl // 'Приготовление:' // nl // '  1. Курицу отварить или запечь, нарезать ломтиками.' // nl // '  2. Овощи нарезать кубиком.' // nl // '  3. Смешать с кукурузой и салатом.' // nl // '  4. Заправить йогуртом с чесноком и зеленью.' // nl // '  5. Солить непосредственно перед подачей.' // nl // ''
  recipes(32) = '' // nl // '### 32. САЛАТ НИСУАЗ (4 порции)' // nl // 'Ингредиенты:' // nl // '  картофель 4 шт, помидоры 3 шт, яйца 2 шт,' // nl // '  тунец 150 г, зелёная фасоль 150 г,' // nl // '  оливковое масло 4 ст.л., горчица, уксус.' // nl // 'Приготовление:' // nl // '  1. Картофель отварить, остудить, нарезать дольками.' // nl // '  2. Фасоль отварить до мягкости, остудить.' // nl // '  3. Яйца отварить вкрутую и разрезать.' // nl // '  4. Заправка: масло, горчица, уксус, соль.' // nl // '  5. Выложить слоями, полить заправкой, сверху тунец.' // nl // ''
  recipes(33) = '' // nl // '### 33. САЛАТ с тунцом (4 порции)' // nl // 'Ингредиенты:' // nl // '  тунец в собственном соку 300 г, яйца 3 шт,' // nl // '  огурцы 3 шт, помидоры 2 шт, листья салата,' // nl // '  оливковое масло 2 ст.л., лимон, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Отварить яйца (10 мин), остудить.' // nl // '  2. Овощи нарезать кубиком, салат порвать.' // nl // '  3. Тунец размять вилкой, отбросить жидкость.' // nl // '  4. Смешать всё, заправить маслом и лимоном.' // nl // '  5. Посыпать зеленью. Подавать сразу.' // nl // ''
  recipes(34) = '' // nl // '### 34. КАПУСТА квашеная с морковью (4 порции)' // nl // 'Ингредиенты:' // nl // '  капуста квашеная 500 г, морковь 2 шт,' // nl // '  подсолнечное масло 3 ст.л., сахар 1 ч.л., соль.' // nl // 'Приготовление:' // nl // '  1. Капусту перебрать, отжать излишки сока.' // nl // '  2. Морковь натереть на крупной тёрке.' // nl // '  3. Смешать, добавить масло и сахар.' // nl // '  4. Подавать как закуску или гарнир к мясу.' // nl // ''
  recipes(35) = '' // nl // '### 35. САЛАТ из свежей капусты (4 порции)' // nl // 'Ингредиенты:' // nl // '  капуста белокочанная 500 г, морковь 1 шт,' // nl // '  яблоко 1 шт, чеснок 2 зубчика,' // nl // '  растительное масло 3 ст.л., уксус, сахар, соль.' // nl // 'Приготовление:' // nl // '  1. Капусту мелко нашинковать и помять с солью 5 мин.' // nl // '  2. Слить сок, который выделится.' // nl // '  3. Добавить натёртую морковь и тёртое яблоко.' // nl // '  4. Заправить маслом, уксусом, сахаром, чесноком.' // nl // ''
  recipes(36) = '' // nl // '### 36. АДЖИКА домашняя (300 г)' // nl // 'Ингредиенты:' // nl // '  перец чили 200 г, томаты 500 г, чеснок 100 г,' // nl // '  хмели-сунели 1 ст.л., кориандр, соль, уксус.' // nl // 'Приготовление:' // nl // '  1. Томаты и перец пропустить через мясорубку.' // nl // '  2. Добавить соль и кипятить 20 мин на слабом огне.' // nl // '  3. За 5 мин до готовности добавить чеснок и специи.' // nl // '  4. Положить в стерилизованные банки, уксус в конце.' // nl // '  5. Хранить в холодильнике до 3 месяцев.' // nl // ''
  recipes(37) = '' // nl // '### 37. ОВОЩНАЯ закуска с чесночным соусом (4 порции)' // nl // 'Ингредиенты:' // nl // '  баклажан 1 шт, кабачок 1 шт, перец 1 шт,' // nl // '  чеснок 4 зубчика, майонез 100 г, зелень,' // nl // '  оливковое масло 3 ст.л., соль-перец.' // nl // 'Приготовление:' // nl // '  1. Овощи нарезать кружком, посолить и обжарить с двух сторон.' // nl // '  2. Чеснок растереть с солью в пасту.' // nl // '  3. Смешать чеснок с майонезом и зеленью.' // nl // '  4. Подавать тёплыми, сбрызнув маслом.' // nl // ''
  recipes(38) = '' // nl // '### 38. ПАШТЕТ из курицы (8 порций)' // nl // 'Ингредиенты:' // nl // '  куриное филе 600 г, сливочное масло 150 г,' // nl // '  морковь 1 шт, лук 1 шт, чеснок 2 зубчика,' // nl // '  коньяк 2 ст.л., соль-перец, лавровый лист.' // nl // 'Приготовление:' // nl // '  1. Филе нарезать, залить коньяком и мариновать 1 ч.' // nl // '  2. Добавить лук, морковь, чеснок, лавровый лист.' // nl // '  3. Запечь при 180 градусах 45 мин.' // nl // '  4. Измельчить блендером с маслом в паштет.' // nl // '  5. Переложить в форму и убрать в холодильник.' // nl // ''
  recipes(39) = '' // nl // '### 39. ХОЛОДЕЦ из курицы (8 порций)' // nl // 'Ингредиенты:' // nl // '  куриные окорочка 1 кг, говяжья голяшка 300 г,' // nl // '  лук 2 шт, морковь 1 шт, чеснок 5 зубчиков,' // nl // '  соль, перец горошком, лавровый лист.' // nl // 'Приготовление:' // nl // '  1. Мясо залить водой, варить 2 ч на слабом огне.' // nl // '  2. За час до готовности добавить лук, морковь, специи.' // nl // '  3. Отвар процедить, мясо разобрать волокнами.' // nl // '  4. Залить бульоном, перемешать, разложить в формы.' // nl // '  5. Остудить и убрать в холодильник на ночь.' // nl // ''
  recipes(40) = '' // nl // '### 40. БАКЛАЖАН запечённый с чесноком (4 порции)' // nl // 'Ингредиенты:' // nl // '  баклажаны 2 шт, чеснок 6 зубчиков, майонез 100 г,' // nl // '  сметана 100 г, зелень, масло, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Баклажаны разрезать вдоль, посолить, оставить 20 мин.' // nl // '  2. Обсушить, смазать маслом и запечь при 200 градусах 30 мин.' // nl // '  3. Чеснок растереть с солью.' // nl // '  4. Смешать чеснок с майонезом, сметаной и зеленью.' // nl // '  5. Намазать на горячие баклажаны, прогреть 5 мин.' // nl // ''
  recipes(41) = '' // nl // '### 41. МЯСО по-французски (6 порций)' // nl // 'Ингредиенты:' // nl // '  свинина 800 г, картофель 6 шт, лук 3 шт,' // nl // '  морковь 2 шт, майонез 200 г, сыр 100 г,' // nl // '  горошек 200 г, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Мясо нарезать порционными кусками, отбить, посолить.' // nl // '  2. Обжарить на сильном огне до румяной корочки.' // nl // '  3. Лук и морковь нарезать полукольцами, пассеровать.' // nl // '  4. Выложить слоями мясо, овощи, картофель и горошек.' // nl // '  5. Залить майонезом, посыпать сыром.' // nl // '  6. Запекать при 180 градусах 40-50 мин до золотистой корочки.' // nl // ''
  recipes(42) = '' // nl // '### 42. ГОЛУБЦЫ с мясом и рисом (6 порций)' // nl // 'Ингредиенты:' // nl // '  капуста 1 кг, фарш 500 г, рис 0.5 стакана,' // nl // '  морковь 1 шт, лук 2 шт, томатный сок 250 мл,' // nl // '  соль, перец.' // nl // 'Приготовление:' // nl // '  1. Листья капусты опустить в кипяток на 5 мин.' // nl // '  2. Лук и морковь мелко нарезать, смешать с фаршем.' // nl // '  3. Рис отварить до полуготовности и остудить.' // nl // '  4. Смешать с фаршем, посолить, поперчить.' // nl // '  5. Начинку разложить по листьям, завернуть конвертом.' // nl // '  6. Уложить в кастрюлю в два слоя, залить томатным соком.' // nl // '  7. Тушить на слабом огне 45 мин.' // nl // ''
  recipes(43) = '' // nl // '### 43. ЛЕНИВЫЕ ГОЛУБЦЫ в сметанном соусе (8 порций)' // nl // 'Ингредиенты:' // nl // '  фарш 700 г, капуста 400 г, рис 120 г, яйцо 1 шт,' // nl // '  сметана 400 г, сливки 200 мл, томатный соус 4 ст.л.,' // nl // '  лук 2 шт, чеснок 3 зубчика, сухари, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Капусту мелко нарезать, смешать с фаршем, рисом, луком.' // nl // '  2. Добавить яйцо, соль, перец и перемешать.' // nl // '  3. Сформовать котлетки длиной 8 см, обвалять в сухарях.' // nl // '  4. Обжарить со всех сторон до румяной корочки.' // nl // '  5. Сметану соединить со сливками, томатным соусом и чесноком.' // nl // '  6. Залить соусом и тушить под крышкой 30 мин.' // nl // ''
  recipes(44) = '' // nl // '### 44. ПЕРЕЦ ФАРШИРОВАННЫЙ с мясом и рисом (6 порций)' // nl // 'Ингредиенты:' // nl // '  перец болгарский 6 шт, фарш 500 г, рис 80 г,' // nl // '  морковь 1 шт, лук 1 шт, томатная паста 2 ст.л.,' // nl // '  сметана 150 г, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Рис отварить до полуготовности.' // nl // '  2. Лук и морковь нарезать мелко, смешать с фаршем и рисом.' // nl // '  3. Наполнить перцы, накрыть срезанными крышечками.' // nl // '  4. Уложить в форму, добавить пасту и немного воды.' // nl // '  5. Тушить при 180 градусах 45 мин.' // nl // '  6. Подавать со сметаной.' // nl // ''
  recipes(45) = '' // nl // '### 45. БАКЛАЖАНЫ ФАРШИРОВАННЫЕ (4 порции)' // nl // 'Ингредиенты:' // nl // '  баклажаны 4 шт, фарш 400 г, лук 1 шт, морковь 1 шт,' // nl // '  чеснок 3 зубчика, сыр 100 г, томатная паста 2 ст.л.,' // nl // '  соль-перец.' // nl // 'Приготовление:' // nl // '  1. Баклажаны разрезать пополам, вырезать мякоть.' // nl // '  2. Мякоть нарезать и обжарить с луком и морковью.' // nl // '  3. Смешать с фаршем, чесноком, пастой и сыром.' // nl // '  4. Наполнить половинки баклажанов.' // nl // '  5. Запекать при 190 градусах 35-40 мин.' // nl // ''
  recipes(46) = '' // nl // '### 46. ПЛОВ узбекский с говядиной (6 порций)' // nl // 'Ингредиенты:' // nl // '  говядина 700 г, рис 500 г, морковь 3 шт,' // nl // '  лук 2 шт, чеснок 1 головка, масло 100 мл,' // nl // '  зира 1 ст.л., барбарис, перец, соль.' // nl // 'Приготовление:' // nl // '  1. Мясо нарезать крупными кусками, отварить 40 мин в полуготовности.' // nl // '  2. Лук и морковь нарезать брусочком, отдельно обжарить до золота.' // nl // '  3. Собрать плов в казане слоями: масло, мясо, овощи, рис, специи.' // nl // '  4. Залить горячей водой на 1 см выше риса, не мешать.' // nl // '  5. Довести до кипения и перевести на самый слабый огонь.' // nl // '  6. Чеснок втыкать в рис сверху, варить 45 мин до впитывания.' // nl // '  7. Собрать горкой и дать настояться 20 мин.' // nl // ''
  recipes(47) = '' // nl // '### 47. ПЛОВ с курицей и морковью (5 порций)' // nl // 'Ингредиенты:' // nl // '  куриные бёдра 600 г, рис 400 г, морковь 3 шт,' // nl // '  лук 2 шт, масло 80 мл, зира, кардамон,' // nl // '  перец, вода 900 мл, соль.' // nl // 'Приготовление:' // nl // '  1. Курицу нарезать, обжарить в масле до золота.' // nl // '  2. Лук и морковь нарезать брусочком, обжарить отдельно.' // nl // '  3. Соединить с курицей, посолить, поперчить.' // nl // '  4. Всыпать промытый рис, залить горячей водой.' // nl // '  5. На сильном огне довести до кипения, убавить до минимума.' // nl // '  6. Варить 30-35 мин, в конце собрать горкой.' // nl // ''
  recipes(48) = '' // nl // '### 48. БЕФСТРОГАНОВ с подливой (4 порции)' // nl // 'Ингредиенты:' // nl // '  говядина вырезка 600 г, сметана 200 г, лук 2 шт,' // nl // '  мука 1 ст.л., горчица 1 ч.л., паприка,' // nl // '  масло, соль-перец, паприка сладкая.' // nl // 'Приготовление:' // nl // '  1. Мясо заморозить 30 мин и нарезать поперёк волокон брусочком.' // nl // '  2. Обжарить мясо на сильном огне 3-4 мин, не туша.' // nl // '  3. Лук нарезать полукольцами, обжарить.' // nl // '  4. Посыпать мукой, добавить сметану, горчицу, паприку.' // nl // '  5. Тушить под крышкой 7-10 мин, не кипятить.' // nl // '  6. Подавать с картофельным пюре.' // nl // ''
  recipes(49) = '' // nl // '### 49. ГОВЯДИНА тушёная с овощами (5 порций)' // nl // 'Ингредиенты:' // nl // '  говядина 700 г, картофель 4 шт, морковь 2 шт,' // nl // '  лук 2 шт, перец болгарский 2 шт, томатная паста 2 ст.л.,' // nl // '  бульон 500 мл, соль-перец, лавровый лист.' // nl // 'Приготовление:' // nl // '  1. Мясо нарезать кубиком и обжарить до корочки.' // nl // '  2. Добавить лук, морковь, перец, пасту.' // nl // '  3. Залить горячим бульоном и тушить под крышкой 40 мин.' // nl // '  4. Добавить картофель и варить до готовности 25 мин.' // nl // '  5. Посолить, поперчить, добавить лавровый лист в конце.' // nl // ''
  recipes(50) = '' // nl // '### 50. СТЕЙК говяжий (2 порции)' // nl // 'Ингредиенты:' // nl // '  говяжья вырезка 400 г, соль, перец чёрный,' // nl // '  чеснок 2 зубчика, розмарин, масло оливковое.' // nl // 'Приготовление:' // nl // '  1. Мясо достать из холодильника за 40 мин до готовки.' // nl // '  2. Натереть солью, перцем и чесноком с обеих сторон.' // nl // '  3. Прогреть сковороду до дыма, капнуть масло.' // nl // '  4. Жарить по 3-4 мин на сторону до румяной корочки.' // nl // '  5. Отдохнуть 5-7 мин, нарезать поперёк волокон.' // nl // '  6. Подавать с солью морской и гарниром.' // nl // ''
  recipes(51) = '' // nl // '### 51. КУРИНАЯ ГРУДКА на гриле (3 порции)' // nl // 'Ингредиенты:' // nl // '  филе курицы 600 г, соевый соус 2 ст.л.,' // nl // '  оливковое масло 2 ст.л., мёд 1 ст.л.,' // nl // '  чеснок 3 зубчика, перец, паприка.' // nl // 'Приготовление:' // nl // '  1. Филе разрезать вдоль на две части.' // nl // '  2. Смешать соевый соус, масло, мёд, чеснок и специи.' // nl // '  3. Мариновать 30 мин минимум.' // nl // '  4. Разогреть решётку до сильного жара.' // nl // '  5. Жарить по 5-6 мин, перевернув один раз.' // nl // '  6. Довести до 75 градусов внутри, отдохнуть 5 мин.' // nl // ''
  recipes(52) = '' // nl // '### 52. КУРИЦА с картошкой в духовке (4 порции)' // nl // 'Ингредиенты:' // nl // '  куриные бёдра 700 г, картофель 700 г,' // nl // '  лук 2 шт, морковь 1 шт, чеснок 4 зубчика,' // nl // '  масло, паприка, соль-перец, зелень.' // nl // 'Приготовление:' // nl // '  1. Курицу и картофель нарезать крупными кусками.' // nl // '  2. Лук и морковь нарезать полукольцами.' // nl // '  3. Всё смешать с маслом и специями в большой форме.' // nl // '  4. Выложить в один слой, накрыть фольгой.' // nl // '  5. Запекать при 200 градусах 30 мин.' // nl // '  6. Снять фольгу и запекать ещё 20 мин до румянца.' // nl // ''
  recipes(53) = '' // nl // '### 53. КУРИНЫЕ СЕРДЕЧКИ в сметане (4 порции)' // nl // 'Ингредиенты:' // nl // '  сердечки 600 г, сметана 200 г, лук 2 шт,' // nl // '  чеснок 3 зубчика, мука 1 ст.л., соль-перец, зелень.' // nl // 'Приготовление:' // nl // '  1. Сердечки промыть, снять плёнки, разрезать пополам.' // nl // '  2. Обжарить на сильном огне 5-6 мин до румянца.' // nl // '  3. Добавить лук и чеснок, пассеровать.' // nl // '  4. Посыпать мукой, влить сметану и немного воды.' // nl // '  5. Тушить под крышкой 15 мин.' // nl // '  6. Солить в конце — иначе сердечки будут жёсткими.' // nl // ''
  recipes(54) = '' // nl // '### 54. СВИНАЯ ОТБИВНАЯ (4 порции)' // nl // 'Ингредиенты:' // nl // '  свиная вырезка 600 г, яйцо 1 шт, мука, сухари,' // nl // '  соль-перец, масло для жарки.' // nl // 'Приготовление:' // nl // '  1. Мясо нарезать на куски по 150 г.' // nl // '  2. Отбить тяпкой через плёнку до толщины 8 мм.' // nl // '  3. Посолить, поперчить, слегка отбить яйцом.' // nl // '  4. Обвалять в муке и сухарях.' // nl // '  5. Жарить на сковороде по 4-5 мин с каждой стороны.' // nl // '  6. Довести в духовке при 190 градусах 15 мин.' // nl // ''
  recipes(55) = '' // nl // '### 55. ЛЮЛЯ-КЕБАБ (4 порции)' // nl // 'Ингредиенты:' // nl // '  баранина 700 г, лук 2 шт, курдючное сало 50 г,' // nl // '  яйцо 1 шт, зире, кориандр, соль-перец, вода.' // nl // 'Приготовление:' // nl // '  1. Баранину и лук пропустить через мясорубку дважды.' // nl // '  2. Добавить сало, яйцо, специи, соль.' // nl // '  3. Вымешать массу 10-15 мин, влить 100 мл воды — будет сочнее.' // nl // '  4. Отжать и сформовать продолговатые кебабы.' // nl // '  5. Нанизать на шампуры или обжарить на сковороде.' // nl // '  6. Жарить 20-25 мин на среднем огне.' // nl // ''
  recipes(56) = '' // nl // '### 56. СПАГЕТТИ КАРБОНАРА (4 порции)' // nl // 'Ингредиенты:' // nl // '  спагетти 400 г, бекон или грудинка 150 г,' // nl // '  яйца 3 шт, тёртый пармезан 100 г,' // nl // '  оливковое масло, чеснок, соль, чёрный перец.' // nl // 'Приготовление:' // nl // '  1. Спагетти отварить до аль денте, сохранить воду.' // nl // '  2. Бекон нарезать кубиком и подрумянить.' // nl // '  3. Чеснок обжарить до аромата и убрать.' // nl // '  4. Взбить желтки с сыром и перцем в миске.' // nl // '  5. Смешать пасту с беконом, добавить яичную смесь и немного воды.' // nl // '  6. Снять с огня и дать соусу загустеть. Подавать сразу.' // nl // ''
  recipes(57) = '' // nl // '### 57. ПАСТА БОЛОНЬЕЗЕ (4 порции)' // nl // 'Ингредиенты:' // nl // '  тальятелле 400 г, фарш говяжий 500 г,' // nl // '  томаты в соку 700 г, лук 1 шт, морковь 1 шт,' // nl // '  сельдерей 1 стебель, красное вино 100 мл, пармезан.' // nl // 'Приготовление:' // nl // '  1. Обжарить лук, морковь, сельдерей 10 мин.' // nl // '  2. Добавить фарш, обжарить до золотистого цвета.' // nl // '  3. Влить вино, дать выпариться.' // nl // '  4. Добавить томаты и тушить 40 мин.' // nl // '  5. Отварить пасту, соединить с соусом.' // nl // '  6. Посыпать пармезаном.' // nl // ''
  recipes(58) = '' // nl // '### 58. ЛАЗАНЬЯ БОЛОНЬЕЗЕ (8 порций)' // nl // 'Ингредиенты:' // nl // '  листы лазаньи 10 шт, фарш 500 г, молоко 800 мл,' // nl // '  мука 50 г, масло 50 г, пармезан 100 г, томаты 750 г.' // nl // 'Приготовление:' // nl // '  1. Обжарить фарш с луком и томатами 30 мин.' // nl // '  2. Для бешамель: обжарить муку, влить молоко, довести до сметаны.' // nl // '  3. Смазать форму маслом, вылить четверть бешамель.' // nl // '  4. Выложить слои: лист, болоньезе, бешамель, сыр. Повторить 4-5 раз.' // nl // '  5. Накрыть листом, залить бешамель и сыром.' // nl // '  6. Запекать при 180 градусах 25-30 мин.' // nl // ''
  recipes(59) = '' // nl // '### 59. РИЗОТТО с грибами (4 порции)' // nl // 'Ингредиенты:' // nl // '  рис 300 г, белые грибы 300 г, бульон 1.2 л,' // nl // '  лук 1 шт, белое вино 150 мл, пармезан 60 г,' // nl // '  масло сливочное 50 г, оливковое масло, тимьян.' // nl // 'Приготовление:' // nl // '  1. Лук мелко нарезать, обжарить с маслом.' // nl // '  2. Добавить белое вино, дать выпариться.' // nl // '  3. Всыпать рис, прогреть до впитывания масла.' // nl // '  4. Вливать бульон по 150 мл, помешивая, 35-40 мин.' // nl // '  5. Грибы обжарить отдельно и в конце подмешать.' // nl // '  6. Снять с огня, вмешать масло и пармезан.' // nl // ''
  recipes(60) = '' // nl // '### 60. ПАСТА с креветками и чесноком (3 порции)' // nl // 'Ингредиенты:' // nl // '  спагетти 300 г, креветки 400 г, чеснок 4 зубчика,' // nl // '  оливковое масло 4 ст.л., халапеньо, помидоры черри 150 г,' // nl // '  петрушка, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Чеснок и халапеньо обжарить на масле до аромата.' // nl // '  2. Добавить креветки, обжарить 2 мин.' // nl // '  3. Влить вино или бульон, добавить черри.' // nl // '  4. Отварить пасту, соединить с соусом.' // nl // '  5. Посыпать петрушкой и подавать сразу.' // nl // ''
  recipes(61) = '' // nl // '### 61. РАВИОЛИ с творогом и шпинатом (4 порции)' // nl // 'Ингредиенты:' // nl // '  мука 400 г, яйца 2 шт, творог 300 г, шпинат 200 г,' // nl // '  сыр пармезан 80 г, мускатный орех, соль.' // nl // 'Приготовление:' // nl // '  1. Замесить крутое тесто из муки и яиц, отложить на 30 мин.' // nl // '  2. Шпинат припустить, отжать и мелко нарезать.' // nl // '  3. Смешать с творогом, сыром, мускатным орехом и солью.' // nl // '  4. Тесто раскатать, вырезать кружки, разложить начинку.' // nl // '  5. Слепить квадратики, выдавив воздух.' // nl // '  6. Отварить 3-4 мин в кипящей воде.' // nl // ''
  recipes(62) = '' // nl // '### 62. МАКАРОНЫ с сыром и зеленью (4 порции)' // nl // 'Ингредиенты:' // nl // '  макароны 400 г, сыр твёрдый 200 г, сливочное масло 50 г,' // nl // '  сливки 200 мл, чеснок 2 зубчика, мускатный орех, зелень.' // nl // 'Приготовление:' // nl // '  1. Макароны отварить в чуть солёной воде.' // nl // '  2. Сыр натереть и растопить со сливками и маслом.' // nl // '  3. Добавить чеснок и мускатный орех.' // nl // '  4. Соединить пасту с соусом.' // nl // '  5. Посыпать зеленью и подавать.' // nl // ''
  recipes(63) = '' // nl // '### 63. КАРТОФЕЛЬНОЕ ПЮРЕ (4 порции)' // nl // 'Ингредиенты:' // nl // '  картофель 1 кг, молоко 200 мл, масло 60 г,' // nl // '  соль-перец, мускатный орех.' // nl // 'Приготовление:' // nl // '  1. Картофель очистить, нарезать и залить холодной водой.' // nl // '  2. Довести до кипения и варить 20-25 мин до мягкости.' // nl // '  3. Слить воду, растереть картофель толкушкой.' // nl // '  4. Влить молоко и масло, взбить.' // nl // '  5. Посолить и добавить мускатный орех.' // nl // ''
  recipes(64) = '' // nl // '### 64. ГРЕЧКА с грибами (4 порции)' // nl // 'Ингредиенты:' // nl // '  гречка 300 г, грибы 400 г, лук 1 шт, чеснок 3 зубчика,' // nl // '  масло растительное 3 ст.л., соль-перец.' // nl // 'Приготовление:' // nl // '  1. Грибы обжарить до испарения жидкости.' // nl // '  2. Добавить лук и чеснок, пассеровать.' // nl // '  3. Гречку перебрать и промыть, обжарить в масле 2 мин.' // nl // '  4. Залить водой 1 к 2, варить 20 мин под крышкой.' // nl // '  5. Посолить в конце, дать упреть 10 мин.' // nl // ''
  recipes(65) = '' // nl // '### 65. РИС с овощами (4 порции)' // nl // 'Ингредиенты:' // nl // '  рис 300 г, морковь 2 шт, кабачок 1 шт,' // nl // '  перец болгарский 1 шт, горошек 100 г, соевый соус 2 ст.л.,' // nl // '  масло кунжутное, чеснок, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Рис отварить до полуготовности и откинуть.' // nl // '  2. Овощи нарезать кубиком, обжарить 7-8 мин.' // nl // '  3. Добавить горошек и чеснок.' // nl // '  4. Всыпать рис, соевый соус и 50 мл воды.' // nl // '  5. Перемешать и прогреть 5 мин на сильном огне.' // nl // ''
  recipes(66) = '' // nl // '### 66. ВЕРМИШЕЛЬ с копчёностями (4 порции)' // nl // 'Ингредиенты:' // nl // '  вермишель 400 г, бекон 200 г, сосиски 3 шт,' // nl // '  сметана 200 г, лук 1 шт, чеснок 3 зубчика,' // nl // '  зелёный горошек, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Бекон и сосиски нарезать и обжарить 6-7 мин.' // nl // '  2. Добавить лук и чеснок, пассеровать.' // nl // '  3. Всыпать горошек, затем вермишель.' // nl // '  4. Залить сметаной и 150 мл воды.' // nl // '  5. Тушить под крышкой 10 мин.' // nl // ''
  recipes(67) = '' // nl // '### 67. ЛАЗАНЬЯ с грибами (6 порций)' // nl // 'Ингредиенты:' // nl // '  листы лазаньи 12 шт, шампиньоны 500 г, лук 1 шт,' // nl // '  моцарелла 200 г, молоко 400 мл, мука 30 г,' // nl // '  сливочное масло 100 г, пармезан, соль-перец.' // nl // 'Приготовление:' // nl // '  1. Грибы и лук обжарить 8-10 мин, в конце чеснок.' // nl // '  2. Сварить бешамель: масло, мука, молоко до загустения.' // nl // '  3. Выложить слои: лист, грибы, соус, сыр. Повторить.' // nl // '  4. Накрыть листом, полить бешамель и пармезаном.' // nl // '  5. Запекать при 190 градусах 25-30 мин.' // nl // ''
  recipes(68) = '' // nl // '### 68. ХАЧАПУРИ по-грузински (4 порции)' // nl // 'Ингредиенты:' // nl // '  мука 500 г, кефир 250 мл, яйцо 1 шт,' // nl // '  творог 300 г, сыр твёрдый 150 г, соль.' // nl // 'Приготовление:' // nl // '  1. Смешать муку, кефир, яйцо, соль и замесить тесто.' // nl // '  2. Оставить на 20 мин под полотенцем.' // nl // '  3. Растянуть в лепёшку, смазать начинкой из творога и сыра.' // nl // '  4. Сделать бортики и сложить хачапури конвертом.' // nl // '  5. Выпекать при 200 градусах 20-25 мин.' // nl // ''
  recipes(69) = '' // nl // '### 69. ПИЦЦА «МАРГАРИТА» (2 пиццы)' // nl // 'Ингредиенты:' // nl // '  мука 500 г, вода 300 мл, дрожжи 7 г, оливковое масло 2 ст.л.,' // nl // '  томатный соус 200 г, моцарелла 250 г,' // nl // '  базилик, соль.' // nl // 'Приготовление:' // nl // '  1. Замесить тесто, оставить на 1 час для брожения.' // nl // '  2. Разделить на 2 части, растянуть в лепёшки.' // nl // '  3. Нанести соус, разложить моцареллу и базилик.' // nl // '  4. Выпекать при максимальной температуре 8-10 мин.' // nl // ''
  recipes(70) = '' // nl // '### 70. ЧЕБУРЕКИ с мясом (12 шт)' // nl // 'Ингредиенты:' // nl // '  мука 500 г, вода 250 мл, соль 1 ч.л.,' // nl // '  фарш свино-говяжий 400 г, лук 2 шт,' // nl // '  чеснок 3 зубчика, перец, яйцо 1 шт.' // nl // 'Приготовление:' // nl // '  1. Замесить крутое тесто, отложить на 30 мин.' // nl // '  2. Лук мелко нарезать, смешать с фаршем и специями.' // nl // '  3. Тесто раскатать 1.5 мм, вырезать кружки 10 см.' // nl // '  4. На каждый кружок выложить начинку и защипнуть край.' // nl // '  5. Жарить на сухой сковороде по 3 мин с каждой стороны.' // nl // ''
  recipes(71) = '' // nl // '### 71. ОЛАДЬИ на кефире (4 порции)' // nl // 'Ингредиенты:' // nl // '  мука 300 г, кефир 500 мл, яйца 2 шт,' // nl // '  сахар 2 ст.л., сода 1 ч.л., масло для жарки.' // nl // 'Приготовление:' // nl // '  1. Смешать кефир с содой, подождать 10 мин.' // nl // '  2. Добавить яйца, сахар, муку, замесить тесто.' // nl // '  3. Оставить на 15 мин для набухания.' // nl // '  4. Выкладывать ложкой на разогретую сковороду.' // nl // '  5. Жарить по 2 мин с каждой стороны до румянца.' // nl // ''
  recipes(72) = '' // nl // '### 72. ПИЦЦА «ПЕППЕРОНИ» (2 пиццы)' // nl // 'Ингредиенты:' // nl // '  мука 500 г, вода 300 мл, дрожжи 7 г,' // nl // '  томатный соус 200 г, моцарелла 250 г,' // nl // '  пепперони 200 г, орегано, масло.' // nl // 'Приготовление:' // nl // '  1. Замесить и поднять тесто 1 час.' // nl // '  2. Растянуть в лепёшки, нанести соус.' // nl // '  3. Разложить моцареллу, сверху пепперони.' // nl // '  4. Выпекать при максимуме 8-10 мин.' // nl // ''
  recipes(73) = '' // nl // '### 73. ЗАПЕКАНКА картофельная с мясом (6 порций)' // nl // 'Ингредиенты:' // nl // '  картофель 1 кг, фарш 500 г, лук 2 шт,' // nl // '  морковь 1 шт, сметана 300 г, сыр 100 г,' // nl // '  соль-перец.' // nl // 'Приготовление:' // nl // '  1. Картофель нарезать тонкими кружками, солить не нужно.' // nl // '  2. Фарш обжарить с луком и морковью 10 мин.' // nl // '  3. Форму смазать, выложить слои картофель и фарш.' // nl // '  4. Залить сметаной, посыпать сыром.' // nl // '  5. Запекать при 180 градусах 45-55 мин.' // nl // ''
  recipes(74) = '' // nl // '### 74. КАРТОФЕЛЬ ФРИ в духовке (4 порции)' // nl // 'Ингредиенты:' // nl // '  картофель 1 кг, масло подсолнечное 3 ст.л.,' // nl // '  соль, паприка, уксус яблочный 1 ст.л.' // nl // 'Приготовление:' // nl // '  1. Картофель вымыть, разрезать на брусочки.' // nl // '  2. Замочить в холодной воде 20 мин, обсушить.' // nl // '  3. Обвалять в масле и специях.' // nl // '  4. Выложить в один слой на пергамент.' // nl // '  5. Запекать при 220 градусах 25-30 мин, один раз перевернув.' // nl // ''
