  recipes(79) = '' // nl // '### 79. БУРГЕР домашний (4 порции)' // nl // 'Ингредиенты:' // nl // '  говядина 700 г, булочки 4 шт, сыр чеддер 4 ломтика,' // nl // '  салат 100 г, помидор 2 шт, лук 1 шт, огурцы солёные,' // nl // '  горчица, кетчуп, чесночный соус.' // nl // 'Приготовление:' // nl // '  1. Мясо пропустить через мясорубку, сформировать котлеты.' // nl // '  2. Жарить на сильном огне по 3 мин с каждой стороны.' // nl // '  3. Надрезать булку, подсушить на сковороде срезом вверх.' // nl // '  4. Собрать: соус, салат, котлета, сыр, овощи, соус.' // nl // '  5. Накрыть верхней булкой и подавать сразу.' // nl // ''
  recipes(80) = '' // nl // '### 80. ТАКО с говядиной (4 порции)' // nl // 'Ингредиенты:' // nl // '  говядина 500 г, тортильи 8 шт, фасоль 200 г,' // nl // '  кукуруза 100 г, помидор 3 шт, лук 1 шт,' // nl // '  чили, сыр, лайм, специи.' // nl // 'Приготовление:' // nl // '  1. Мясо обжарить с чили и луком 8 мин, посыпать специями.' // nl // '  2. Фасоль размять и прогреть со специями.' // nl // '  3. Тортильи прогреть на сухой сковороде по 15 сек.' // nl // '  4. Выложить мясо, фасоль, кукурузу и овощи.' // nl // '  5. Посыпать сыром, сбрызнуть соком лайма.' // nl // ''
  recipes(81) = '' // nl // '### 81. УДОН с овощами (2 порции)' // nl // 'Ингредиенты:' // nl // '  лапша удон 250 г, соевый соус 3 ст.л.,' // nl // '  овощи замороженные 200 г, масло кунжутное,' // nl // '  чеснок 3 зубчика, имбирь 15 г, кунжут, чили.' // nl // 'Приготовление:' // nl // '  1. Отварить удон 3 мин по инструкции, откинуть.' // nl // '  2. Обжарить чеснок, имбирь и чили на кунжутном масле.' // nl // '  3. Добавить овощи, прогреть 5 мин.' // nl // '  4. Влить соевый соус и 50 мл воды, закипятить.' // nl // '  5. Выложить лапшу, перемешать и посыпать кунжутом.' // nl // ''
