  recipes(99) = '' // nl // '### 99. ТАРТ с клубникой (8 порций)' // nl // 'Ингредиенты:' // nl // '  песочное тесто 300 г, клубника 400 г,' // nl // '  желтки 3 шт, сливки 200 мл, сахар 100 г,' // nl // '  желатин 10 г, шоколад белый.' // nl // 'Приготовление:' // nl // '  1. Тесто раскатать в форму, выпечь при 180 градусах 15 мин.' // nl // '  2. Для крема: желтки с сахаром и сливками, варить 5 мин.' // nl // '  3. Добавить распущенный желатин, остудить.' // nl // '  4. Выложить на корж нарезанную клубнику, залить кремом.' // nl // '  5. Охладить до застывания, украсить белым шоколадом.' // nl // ''
  recipes(100) = '' // nl // '### 100. ТВОРожНЫЙ десерт с ягодами (6 порций)' // nl // 'Ингредиенты:' // nl // '  творог 500 г, сливки 33% 150 мл, сахар 80 г,' // nl // '  мёд 2 ст.л., ягоды 300 г, печенье 100 г.' // nl // 'Приготовление:' // nl // '  1. Творог протереть через сито.' // nl // '  2. Взбить творог со сливками и сахаром до крема.' // nl // '  3. Разложить в креманки, охладить.' // nl // '  4. Сверху ягоды и мёд, печенье — в качестве декора.' // nl // ''
  menu = '' // nl // '====================================================' // nl // '             КНИГА РЕЦЕПТОВ — 100 блюд' // nl // '====================================================' // nl // 'Введи номер от 1 до 100, затем Enter.  0 — выход.' // nl // '    1. Борщ             26. Сельдка в шубе   51. Курица гриль     76. Мамалыга' // nl // '    2. Солянка          27. Мимоза           52. Курица с карт.   77. Лаваш' // nl // '    3. Оливье           28. Цезарь           53. Сердечки         78. Шаурма' // nl // '    4. Котлеты кит.     29. Винегрет         54. Отбивная         79. Бургер' // nl // '    5. Блины            30. Табате           55. Люля-кебаб       80. Тако' // nl // '    6. Греческий салат  31. Салат с курицей  56. Карбонара        81. Удон' // nl // '    7. Пельмени         32. Нисуаз           57. Болоньезе        82. Рамен' // nl // '    8. Шашлык           33. Салат с тунцом   58. Лазанья          83. Кимчи' // nl // '    9. Сырники          34. Капуста кваш.    59. Ризотто          84. Азиат. салат' // nl // '   10. Торт шоколад.    35. Салат капустный  60. Паста креветки   85. Йогурт' // nl // '   11. Уха из трески    36. Аджика           61. Равиоли          86. Наполеон' // nl // '   12. Рассольник       37. Овощная закуска  62. Макароны сыр     87. Медовик' // nl // '   13. Щи               38. Паштет           63. Пюре             88. Чизкейк' // nl // '   14. Суп куриный      39. Холодец          64. Гречка грибы     89. Тирамису' // nl // '   15. Окрошка          40. Баклажан чеснок  65. Рис с овощами    90. Панна котта' // nl // '   16. Холодник         41. Мясо по-франц.   66. Вермишель копч.  91. Шарлотка' // nl // '   17. Суп-пюре тыква   42. Голубцы          67. Лазанья грибы    92. Торт морковн.' // nl // '   18. Том Ям           43. Голубцы ленивые  68. Хачапури         93. Пирог яблочн.' // nl // '   19. Харчо            44. Перец фаршир.    69. Пицца Маргарита  94. Эклеры' // nl // '   20. Сырный суп       45. Баклажаны        70. Чебуреки         95. Мадлен' // nl // '   21. Минестроне       46. Плов узбекский   71. Оладьи           96. Кекс на сметане' // nl // '   22. Суп чечевица     47. Плов с курицей   72. Пицца Пепперони  97. Печенье овсян.' // nl // '   23. Уха красная      48. Бефстроганов     73. Запеканка        98. Брауни' // nl // '   24. Лапша            49. Говядина туш.    74. Картофель фри    99. Тарт клубника' // nl // '   25. Бульон куриный   50. Стейк            75. Драники         100. Творожный дес.' // nl // '> '
  msg_bad = '' // nl // '[!] Нет такого рецепта. Введи число от 1 до 100 или 0 для выхода.' // nl // ''
  msg_pause = '' // nl // '--- Нажми Enter, чтобы вернуться в меню ---' // nl // ''
  msg_bye = '' // nl // 'Приятного аппетита!' // nl // ''
  menu_len = len_trim(menu) + 1

  do
    write(*, '(A)', advance='no') menu(1:menu_len)
    flush(6)
    read(*, '(A)', iostat=ios) line
    if (ios /= 0) then
      write(*, '(A)') msg_bye(1:efflen(msg_bye))
      stop
    end if

    n = -1
    k = len_trim(line)
    val = 0
    if (k >= 1 .and. k <= 3) then
      n = 0
      do i = 1, k
        c = iachar(line(i:i))
        if (c < 48 .or. c > 57) then
          n = -1
          exit
        end if
        val = val * 10 + (c - 48)
      end do
      if (n == 0) n = val
    end if

    if (n == -1) then
      write(*, '(A)') msg_bad(1:efflen(msg_bad))
    else if (n == 0) then
      write(*, '(A)') msg_bye(1:efflen(msg_bye))
      stop
    else if (n > LAST) then
      write(*, '(A)') msg_bad(1:efflen(msg_bad))
    else
      write(*, '(A)') recipes(n)(1:efflen(recipes(n)))
      write(*, '(A)') msg_pause(1:efflen(msg_pause))
      flush(6)
      read(*, '(A)', iostat=ios) line
      if (ios /= 0) then
        write(*, '(A)') msg_bye(1:efflen(msg_bye))
        stop
      end if
    end if
  end do

contains

  integer function efflen(s)
    character(len=*), intent(in) :: s
    integer :: m
    m = len_trim(s)
    do while (m >= 1)
      if (s(m:m) == ' ' .or. iachar(s(m:m)) == 10) then
        m = m - 1
      else
        exit
      end if
    end do
    efflen = m
  end function efflen

end program cookbook
